app/components/editor/frontmatter-fields.source:
// A post's frontmatter as labelled fields: editable in the editor, read-only on the AI draft page.
// The editor keeps the one source string; these fields read from it and write back through
// setField, so a key they do not show is never touched (app/lib/frontmatter.ts).

import { Field } from "capsomer/react/field";

import { BANNER_WORD, FIELDS, readFields, setField, splitSource, joinSource, type FieldKey } from "~/lib/frontmatter";
import { legalTypeOf, marker, sectionsUsed } from "~/lib/legal";

const HINTS: Partial<Record<FieldKey, string>> = {
  tags: "Separated by commas.",
  key_takeaways: "One per line.",
  date: "Year, month, day: 2026-10-04.",
  site_name: "Filled into shared text as {{site_name}}.",
  operator_name: "Filled into shared text as {{operator_name}}.",
  contact: "An email address or a path. Shared text: {{contact}}.",
  jurisdiction: "Shared text: {{jurisdiction}}.",
  data_held: "What this site collects, separated by commas. Shared text: {{data_held}}.",
  last_updated: "Set when the Owner publishes a changed text. Edit it only to correct it.",
  banner: `Shows the word "${BANNER_WORD}" on the page until you are satisfied with it.`,
};

/** Sets one field in a source and returns the whole source. A source with no frontmatter is returned as it was. */
export function withField(source: string, key: FieldKey, value: string): string {
  const parts = splitSource(source);
  return parts.front === null ? source : joinSource({ ...parts, front: setField(parts.front, key, value) });
}

export type SectionChoice = { key: string; title: string };

export function FrontmatterFields({ source, onChange, readOnly, sections = [] }: { source: string; onChange?: (next: string) => void; readOnly?: boolean; sections?: SectionChoice[] }) {
  const { front, body } = splitSource(source);
  if (front === null) return null;
  const values = readFields(front);
  const legal = legalTypeOf(source) !== null;
  const shown = FIELDS.filter((f) => (f.on === "all" || f.on === (legal ? "legal" : "post")) && (!readOnly || values[f.key] !== ""));
  if (shown.length === 0) return null;
  const used = sectionsUsed(body);
  const unused = sections.filter((s) => !used.includes(s.key));
  return (
    <fieldset className="app-fm">
      <legend>{legal ? "Legal page details" : "Post details"}</legend>
      {shown.map((f) => {
        if (f.kind === "flag") {
          return (
            <div key={f.key} className="app-fm-field" data-wide="">
              <Field label={f.label} help={HINTS[f.key]}>
                <input type="checkbox" checked={values[f.key] !== ""} disabled={readOnly || !onChange} onChange={(event) => onChange?.(withField(source, f.key, event.target.checked ? BANNER_WORD : ""))} />
              </Field>
            </div>
          );
        }
        const wide = f.kind !== "line" && f.key !== "tags";
        const props = {
          className: "cap-input",
          value: values[f.key],
          readOnly: readOnly || !onChange,
          onChange: (event: { target: { value: string } }) => onChange?.(withField(source, f.key, event.target.value)),
        };
        return (
          <div key={f.key} className="app-fm-field" data-wide={wide ? "" : undefined}>
            <Field label={f.label} help={HINTS[f.key]}>
              {f.kind === "text" || f.kind === "lines" ? <textarea {...props} rows={f.kind === "lines" ? 4 : 2} /> : <input {...props} type="text" />}
            </Field>
          </div>
        );
      })}
      {legal && !readOnly && onChange && unused.length > 0 ? (
        <div className="app-fm-field" data-wide="">
          <Field label="Add a shared section" help="Written at the end of the text. It is filled in from the details above each time the page is saved to the site; edit its wording on the Legal tab, not here.">
            <select
              className="cap-input"
              value=""
              onChange={(event) => {
                const key = event.target.value;
                if (key) onChange(`${source.replace(/\n*$/, "")}\n\n${marker(key)}\n`);
              }}
            >
              <option value="">Choose a section</option>
              {unused.map((s) => (
                <option key={s.key} value={s.key}>
                  {s.title}
                </option>
              ))}
            </select>
          </Field>
        </div>
      ) : null}
    </fieldset>
  );
}

app/lib/access.server.ts.source:
// Identity comes only from the Access token Cloudflare puts on every request it lets through.
//
// NOT ctx.access. A Worker with Static Assets (the Vite plugin adds them for React Router) runs
// behind a router Worker that does not pass ctx.access through, so this Worker verifies the
// Cf-Access-Jwt-Assertion header itself against the team's certs, issuer and AUD.

import { createRemoteJWKSet, jwtVerify, type JWTVerifyGetKey } from "jose";

export const ACCESS_JWT_HEADER = "cf-access-jwt-assertion";

export type AccessResult =
  | { ok: true; email: string }
  | { ok: false; reason: "not-configured" | "no-token" | "invalid-token" | "no-email" };

/** The issuer exactly as Access writes it: the team domain with no trailing slash. */
export function teamIssuer(teamDomain: string): string {
  return teamDomain.trim().replace(/\/+$/, "");
}

const remoteKeys = new Map<string, JWTVerifyGetKey>();

/** The team's signing keys, fetched and cached by jose, one set per team domain. */
export function accessKeys(teamDomain: string): JWTVerifyGetKey {
  const issuer = teamIssuer(teamDomain);
  let keys = remoteKeys.get(issuer);
  if (!keys) {
    keys = createRemoteJWKSet(new URL(`${issuer}/cdn-cgi/access/certs`));
    remoteKeys.set(issuer, keys);
  }
  return keys;
}

/**
 * Verifies the request's Access token against one Access application's audience. Every failure is a refusal: a missing setting, a missing
 * header, a bad signature, the wrong issuer or audience, an expired token, or a token with no email.
 */
export async function verifyAccess(
  request: Request,
  config: { teamDomain: string | undefined; audience: string | undefined },
  keys: JWTVerifyGetKey,
): Promise<AccessResult> {
  const teamDomain = config.teamDomain?.trim();
  const audience = config.audience?.trim();
  if (!teamDomain || !audience) return { ok: false, reason: "not-configured" };

  const token = request.headers.get(ACCESS_JWT_HEADER);
  if (!token) return { ok: false, reason: "no-token" };

  let payload;
  try {
    ({ payload } = await jwtVerify(token, keys, {
      issuer: teamIssuer(teamDomain),
      audience,
      algorithms: ["RS256"],
    }));
  } catch {
    return { ok: false, reason: "invalid-token" };
  }

  const email = typeof payload.email === "string" ? payload.email.trim() : "";
  if (!email) return { ok: false, reason: "no-email" };
  return { ok: true, email };
}

app/lib/google/service-account.server.ts.source:
// The Google service account (design decision 6): it reads the manuscripts folder's metadata and
// Search Console, and cannot do anything else. Two walls: it asks Google only for read-only scopes,
// and every request it makes passes an allowlist here, so a write through it is refused in code
// before anything is sent, whatever the scopes would allow.

import { SignJWT } from "jose";

/** Read-only, and no drive.readonly: the index takes metadata, and search asks Drive each time. */
export const SA_SCOPES = ["https://www.googleapis.com/auth/drive.metadata.readonly", "https://www.googleapis.com/auth/webmasters.readonly"];

export const GOOGLE_TOKEN_URL = "https://oauth2.googleapis.com/token";

export type ServiceAccountKey = { clientEmail: string; privateKey: string; privateKeyId: string; tokenUri: string };

export type SaConnection =
  | { state: "connected"; key: ServiceAccountKey }
  | { state: "not-connected"; detail: string }
  | { state: "misconfigured"; detail: string };

export function saConnection(env: Env): SaConnection {
  const raw = env.GOOGLE_SA_KEY?.trim();
  if (!raw) return { state: "not-connected", detail: "GOOGLE_SA_KEY is not set, so the manuscripts index and Search Console are off." };
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(raw) as Record<string, unknown>;
  } catch {
    return { state: "misconfigured", detail: "GOOGLE_SA_KEY is not JSON; set it to the whole key file Google downloads." };
  }
  const { type, client_email, private_key, private_key_id, token_uri } = parsed;
  if (type !== "service_account" || typeof client_email !== "string" || typeof private_key !== "string" || typeof private_key_id !== "string") {
    return { state: "misconfigured", detail: "GOOGLE_SA_KEY is not a service account key file (type, client_email, private_key, private_key_id)." };
  }
  if (!private_key.includes("BEGIN PRIVATE KEY")) return { state: "misconfigured", detail: "GOOGLE_SA_KEY's private_key is not a PKCS#8 PEM key." };
  // A key file pointing its token endpoint anywhere but Google's would hand the signed assertion elsewhere.
  const tokenUri = typeof token_uri === "string" ? token_uri : GOOGLE_TOKEN_URL;
  if (tokenUri !== GOOGLE_TOKEN_URL) return { state: "misconfigured", detail: `GOOGLE_SA_KEY's token_uri is ${tokenUri}, not Google's.` };
  return { state: "connected", key: { clientEmail: client_email, privateKey: private_key, privateKeyId: private_key_id, tokenUri } };
}

export class GoogleNotConnected extends Error {
  constructor(readonly detail: string) {
    super(detail);
    this.name = "GoogleNotConnected";
  }
}

/** A request the service account is not allowed to make: refused here, never sent. */
export class ServiceAccountRefused extends Error {
  constructor(method: string, url: string) {
    super(`The service account may only read; ${method} ${url} was refused before it was sent.`);
    this.name = "ServiceAccountRefused";
  }
}

// Every request the service account may make: listing files (metadata) and Search Console's query,
// a POST that reads. Not files.get, whose alt=media returns a file's content.
const ALLOWED: { method: string; url: RegExp }[] = [
  { method: "GET", url: /^https:\/\/www\.googleapis\.com\/drive\/v3\/files(\?|$)/ },
  { method: "POST", url: /^https:\/\/searchconsole\.googleapis\.com\/webmasters\/v3\/sites\/[^/]+\/searchAnalytics\/query$/ },
];

export function assertReadOnly(method: string, url: string): void {
  const m = method.toUpperCase();
  // alt=media asks for content instead of metadata, wherever it appears.
  const media = new URL(url).searchParams.has("alt") && new URL(url).searchParams.get("alt") !== "json";
  if (media || !ALLOWED.some((a) => a.method === m && a.url.test(url))) throw new ServiceAccountRefused(m, url);
}

type Fetch = typeof fetch;

const tokenCache = new Map<string, { token: string; expires: number }>();

export function clearSaTokenCache(): void {
  tokenCache.clear();
}

/** A signed JWT exchanged at Google's token endpoint for an hour's access token, cached per key. */
export async function saAccessToken(key: ServiceAccountKey, fetcher: Fetch = fetch, now = Date.now()): Promise<string> {
  const cached = tokenCache.get(key.privateKeyId);
  if (cached && cached.expires - 5 * 60_000 > now) return cached.token;
  const pem = key.privateKey.replace(/-----(BEGIN|END) PRIVATE KEY-----/g, "").replace(/\s+/g, "");
  const der = Uint8Array.from(atob(pem), (c) => c.charCodeAt(0));
  const signingKey = await crypto.subtle.importKey("pkcs8", der, { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["sign"]);
  const iat = Math.floor(now / 1000);
  const assertion = await new SignJWT({ scope: SA_SCOPES.join(" ") })
    .setProtectedHeader({ alg: "RS256", kid: key.privateKeyId, typ: "JWT" })
    .setIssuer(key.clientEmail)
    .setAudience(key.tokenUri)
    .setIssuedAt(iat)
    .setExpirationTime(iat + 3600)
    .sign(signingKey);
  const res = await fetcher(key.tokenUri, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer", assertion }).toString(),
  });
  if (!res.ok) {
    const body = (await res.json().catch(() => ({}))) as { error?: string; error_description?: string };
    // invalid_grant is how Google answers a deleted, disabled or expired key.
    throw new Error(`Google refused the service account key (${res.status} ${body.error ?? ""}${body.error_description ? `: ${body.error_description}` : ""}).`);
  }
  const body = (await res.json()) as { access_token: string; expires_in: number };
  tokenCache.set(key.privateKeyId, { token: body.access_token, expires: now + body.expires_in * 1000 });
  return body.access_token;
}

/** The service account's only way to reach Google: read-only by allowlist, then authenticated. */
export function saClient(env: Env, fetcher: Fetch = fetch) {
  const connection = saConnection(env);
  if (connection.state !== "connected") throw new GoogleNotConnected(connection.detail);
  return {
    key: connection.key,
    async request(method: string, url: string, body?: unknown): Promise<Response> {
      assertReadOnly(method, url);
      const token = await saAccessToken(connection.key, fetcher);
      return fetcher(url, {
        method,
        headers: { Authorization: `Bearer ${token}`, ...(body === undefined ? {} : { "Content-Type": "application/json" }) },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
    },
  };
}

app/lib/mentions.server.ts.source:
// Webmentions on a site project (site-api v0.5.0, the mentions group): the queue of what other sites
// sent, and the Owner's decisions on it. Mentions are text strangers chose, so they are shown as text
// and decided here, one site write each, in order. One failing never stops the rest, and every outcome
// is said in plain words.
//
// Roles, checked here so the page, the JSON endpoint and any later tool meet the same rule:
// carrel/design.md says the inbox belongs to Dustin alone, so reading the queue (read_mentions) and
// deciding (decide_mention) are both the Owner's. Change roles.ts, not this file, to open it wider.
//
// Authorship: every write the site carried out writes one row in mention_decisions (migration 0011),
// with the change id Carrel sent the site so the two histories join. A refused write writes nothing.
// The write and the site's cache purge are one unit on the site's side; Carrel reports its answer.

import { MentionId, Version, type MentionItem, type MentionList, type MentionStatus } from "@dustinedwards/site-api";
import { SiteApiError } from "@dustinedwards/site-api/client";
import { drizzle } from "drizzle-orm/d1";

import { mentionDecisions } from "~/db/schema";
import type { Viewer } from "~/lib/people.server";
import type { SiteProject } from "~/lib/projects.server";
import { can, type Action } from "~/lib/roles";
import { siteClient, SiteNotConnected } from "~/lib/sites.server";

export const MAX_MENTION_BATCH = 100;
export const MENTIONS_PER_PAGE = 50;

/** The views of the queue, pending first because it is the one that wants an action. */
export const MENTION_FILTERS = ["pending", "failed", "approved", "rejected", "unverified", "all"] as const;
export type MentionFilter = (typeof MENTION_FILTERS)[number];

export function isMentionFilter(value: string | null | undefined): value is MentionFilter {
  return (MENTION_FILTERS as readonly string[]).includes(value ?? "");
}

export type MentionOp = "approve" | "reject" | "delete";

/** One mention to act on: its id, the version the person saw, and the status they saw it in. */
export type MentionTarget = { id: string; version: string; status: MentionStatus };

/** One mention's outcome. `ok` false means this mention was left as it was; the message says why. */
export type MentionResult = { id: string; ok: boolean; message: string };

export type SweepResult = { ok: true; message: string; removed: { failed: number; rejected: number }; recorded: boolean } | { ok: false; message: string };

/** Who did it: the person, and the AI client when it came through the AI door (credited in the record). */
export type MentionActor = { viewer: Viewer; client?: string };

function requireCan(project: { role: SiteProject["role"] }, action: Action) {
  if (!can(project.role, action)) throw new Response("Forbidden", { status: 403 });
}

/**
 * Whether the site moderates mentions through Carrel, from its meta. A site on an older site API, or
 * one whose adapter has no mentions, says no and the reason is plain; a site that does not answer says that.
 */
export async function mentionsOffered(
  env: Env,
  project: SiteProject,
  fetcher?: typeof fetch,
): Promise<{ offered: true } | { offered: false; reason: string }> {
  requireCan(project, "read_mentions");
  try {
    const meta = await siteClient(env, project.site, fetcher).meta();
    return meta.capabilities.mentions === true ? { offered: true } : { offered: false, reason: "This site does not receive webmentions through Carrel yet." };
  } catch (error) {
    if (error instanceof SiteNotConnected) return { offered: false, reason: error.detail };
    console.error(JSON.stringify({ meta: "failed", error: String(error) }));
    return { offered: false, reason: "The site did not answer, so Carrel cannot tell whether it receives webmentions." };
  }
}

/**
 * One page of the queue. With no filter the queue opens on Pending, and on All when nothing is
 * pending, as the site's own page does. The counts and the number a sweep would remove cover the whole queue.
 */
export async function listMentions(
  env: Env,
  project: SiteProject,
  query: { filter?: MentionFilter | null; cursor?: string },
  fetcher?: typeof fetch,
): Promise<{ filter: MentionFilter; list: MentionList }> {
  requireCan(project, "read_mentions");
  const client = siteClient(env, project.site, fetcher);
  const page = (filter: MentionFilter) =>
    client.mentions.list({
      limit: MENTIONS_PER_PAGE,
      ...(filter === "all" ? {} : { status: filter }),
      ...(query.cursor ? { cursor: query.cursor } : {}),
    });
  if (query.filter) return { filter: query.filter, list: await page(query.filter) };
  const pending = await page("pending");
  if (pending.items.length > 0 || pending.counts.pending > 0) return { filter: "pending", list: pending };
  return { filter: "all", list: await page("all") };
}

const MESSAGES: Record<MentionOp, { done: string }> = {
  approve: { done: "Approved." },
  reject: { done: "Rejected." },
  delete: { done: "Deleted." },
};

const STALE = "This mention changed on the site since the page loaded. It was left as it was; reload to see it.";

/** What went wrong for one mention, said plainly. Anything unexpected is logged and reported, never dropped. */
function failure(id: string, error: unknown): MentionResult {
  if (error instanceof SiteNotConnected) return { id, ok: false, message: error.detail };
  if (error instanceof SiteApiError) {
    if (error.status === 501) return { id, ok: false, message: "The site does not moderate mentions through Carrel yet." };
    if (error.body?.error === "version-conflict") return { id, ok: false, message: STALE };
    if (error.status === 404) return { id, ok: false, message: "The site no longer has this mention. It may have been deleted or swept." };
    if (error.body?.error === "refused") return { id, ok: false, message: error.body.message };
    console.error(JSON.stringify({ mentions: "item-failed", id, status: error.status, code: error.body?.error ?? null }));
    return { id, ok: false, message: "The site did not accept this change. The mention was left as it was." };
  }
  console.error(JSON.stringify({ mentions: "item-failed", id, error: String(error) }));
  return { id, ok: false, message: "Something went wrong with this mention. It was left as it was." };
}

/** Said when the write moved but the site could not clear its cache: the post's page keeps the old mentions for a while. */
const PURGE_FAILED = " The site could not clear its cache, so the post's page may show the old mentions until its cache expires.";

/** The ids and versions to act on: unique, each shaped as a site could hold it. Anything else is reported, not sent. */
export function parseTargets(raw: unknown): { targets: MentionTarget[]; invalid: string[] } {
  const targets: MentionTarget[] = [];
  const invalid: string[] = [];
  const seen = new Set<string>();
  if (!Array.isArray(raw)) return { targets, invalid };
  for (const entry of raw) {
    const e = (entry ?? {}) as Record<string, unknown>;
    const id = typeof e.id === "string" ? e.id : "";
    const status = ["unverified", "pending", "approved", "rejected", "failed"].find((s) => s === e.status) as MentionStatus | undefined;
    if (seen.has(id)) continue;
    seen.add(id);
    if (!MentionId.safeParse(id).success || !Version.safeParse(e.version).success || !status) invalid.push(id || "(no id)");
    else targets.push({ id, version: e.version as string, status });
  }
  return { targets, invalid };
}

async function record(
  env: Env,
  project: SiteProject,
  actor: MentionActor,
  row: { mentionId: string | null; action: "approve" | "reject" | "delete" | "sweep"; statusBefore: MentionStatus | null; statusAfter: MentionStatus | null; changeId: string },
): Promise<boolean> {
  try {
    await drizzle(env.DB).insert(mentionDecisions).values({
      projectId: project.id,
      personId: actor.viewer.id,
      client: actor.client ?? null,
      ...row,
    });
    return true;
  } catch (error) {
    console.error(JSON.stringify({ record: "failed", action: row.action, mentionId: row.mentionId, changeId: row.changeId, error: String(error) }));
    return false;
  }
}

/**
 * Approves, rejects or deletes each mention, in order, each with its own change id and its own
 * authorship row. The role is checked once before the site is asked anything. Each write carries the
 * version the person saw, so a mention the site changed since (re-sent, decided elsewhere) is refused
 * as stale and stays.
 */
export async function decideMentions(
  env: Env,
  project: SiteProject,
  actor: MentionActor,
  op: MentionOp,
  rawTargets: unknown,
  fetcher?: typeof fetch,
): Promise<MentionResult[]> {
  requireCan(project, "decide_mention");
  const { targets, invalid } = parseTargets(rawTargets);
  if (targets.length + invalid.length === 0) throw new Response("Choose at least one mention.", { status: 400 });
  if (targets.length + invalid.length > MAX_MENTION_BATCH) throw new Response(`At most ${MAX_MENTION_BATCH} mentions at a time.`, { status: 400 });

  const results: MentionResult[] = invalid.map((id) => ({ id, ok: false, message: "That is not a mention Carrel can send to the site, so it was not sent." }));
  const client = siteClient(env, project.site, fetcher);
  for (const target of targets) {
    const changeId = crypto.randomUUID();
    try {
      let statusAfter: MentionStatus | null = null;
      let purged: boolean | null;
      if (op === "delete") {
        ({ purged } = await client.mentions.delete(target.id, { expectedVersion: target.version, changeId }));
      } else {
        const written = await client.mentions.decide(target.id, { decision: op, expectedVersion: target.version, changeId });
        statusAfter = written.status;
        purged = written.purged;
      }
      const recorded = await record(env, project, actor, { mentionId: target.id, action: op, statusBefore: target.status, statusAfter, changeId });
      results.push({
        id: target.id,
        ok: true,
        message: MESSAGES[op].done + (purged === false ? PURGE_FAILED : "") + (recorded ? "" : " Carrel could not save the record of it; tell the Owner."),
      });
    } catch (error) {
      results.push(failure(target.id, error));
    }
  }
  return results;
}

/** Removes the failed and rejected mentions past the site's retention windows. Owner only; the site decides what is expired. */
export async function sweepMentions(env: Env, project: SiteProject, actor: MentionActor, fetcher?: typeof fetch): Promise<SweepResult> {
  requireCan(project, "decide_mention");
  const changeId = crypto.randomUUID();
  try {
    const { removed } = await siteClient(env, project.site, fetcher).mentions.sweep(changeId);
    const recorded = await record(env, project, actor, { mentionId: null, action: "sweep", statusBefore: null, statusAfter: null, changeId });
    return {
      ok: true,
      removed,
      recorded,
      message:
        `Removed ${removed.failed} failed and ${removed.rejected} rejected mention${removed.failed + removed.rejected === 1 ? "" : "s"} past their retention window.` +
        (recorded ? "" : " Carrel could not save the record of it; tell the Owner."),
    };
  } catch (error) {
    const { message } = failure("sweep", error);
    return { ok: false, message };
  }
}

export type { MentionItem, MentionList };

app/lib/refresh.server.ts.source:
// The cron's index refresh: every project that is a connected site. A site that is not connected yet
// is skipped quietly; one that fails is logged, and the health check is where it gets reported.

import { isNotNull } from "drizzle-orm";
import { drizzle } from "drizzle-orm/d1";

import { projects } from "~/db/schema";
import { refreshIndex, type RefreshResult } from "~/lib/index.server";
import { isSiteId, siteConnection } from "~/lib/sites.server";

export async function refreshAllSites(env: Env, fetcher?: typeof fetch): Promise<Record<string, RefreshResult | string>> {
  const rows = await drizzle(env.DB)
    .select({ id: projects.id, slug: projects.slug, site: projects.site })
    .from(projects)
    .where(isNotNull(projects.site))
    .all();
  const out: Record<string, RefreshResult | string> = {};
  for (const row of rows) {
    if (!isSiteId(row.site)) continue;
    if (siteConnection(env, row.site).state !== "connected") {
      out[row.slug] = "not connected";
      continue;
    }
    try {
      out[row.slug] = await refreshIndex(env, { id: row.id, site: row.site }, fetcher);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(JSON.stringify({ refresh: "failed", project: row.slug, error: message }));
      out[row.slug] = `failed: ${message}`;
    }
  }
  return out;
}

app/routes/ai-draft.tsx.source:
// One AI draft, read-only, beside the person's own. Using it is the person's decision: "Use as my
// draft" puts its text in their working draft (autosave), where they edit it before anything reaches
// the site. Nothing here writes to the site.

import { useRef, useState } from "react";
import { Form, Link, redirect, useNavigation } from "react-router";
import { Banner } from "capsomer/react/banner";
import { Button } from "capsomer/react/button";
import { ConfirmDialog } from "capsomer/react/confirm-dialog";
import { Panel } from "capsomer/react/panel";
import { Segmented } from "capsomer/react/segmented";
import { Time } from "capsomer/react/time";

import { FrontmatterFields } from "~/components/editor/frontmatter-fields";
import { PageHead } from "~/components/page-head";

import { readAiDraft } from "~/lib/ai.server";
import { autosave } from "~/lib/content.server";
import { getEnv, getViewer } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { can } from "~/lib/roles";

import type { Route } from "./+types/ai-draft";

export function meta() {
  return [{ title: "AI draft · Carrel" }];
}

function draftId(value: string | undefined): number {
  const id = Number(value);
  if (!Number.isInteger(id) || id <= 0) throw new Response("Not found", { status: 404 });
  return id;
}

export async function loader({ params, context }: Route.LoaderArgs) {
  const env = getEnv(context);
  const viewer = getViewer(context);
  const project = await requireSiteProject(env.DB, viewer, params.project, "read");
  const draft = await readAiDraft(env.DB, project, viewer, params.item, draftId(params.id));
  return {
    project: { slug: project.slug, name: project.name },
    itemId: params.item,
    draft: { id: draft.id, client: draft.client, note: draft.note, createdAt: draft.createdAt, source: draft.source, baseVersion: draft.baseVersion },
    canEdit: can(project.role, "edit"),
  };
}

export async function action({ params, context }: Route.ActionArgs) {
  const env = getEnv(context);
  const viewer = getViewer(context);
  const project = await requireSiteProject(env.DB, viewer, params.project, "edit");
  const draft = await readAiDraft(env.DB, project, viewer, params.item, draftId(params.id));
  await autosave(env.DB, project, viewer, params.item, { source: draft.source, baseVersion: draft.baseVersion });
  return redirect(`/p/${project.slug}/e/${encodeURIComponent(params.item)}`);
}

export default function AiDraft({ loaderData }: Route.ComponentProps) {
  const { project, itemId, draft, canEdit } = loaderData;
  const editor = `/p/${project.slug}/e/${encodeURIComponent(itemId)}`;
  const busy = useNavigation().state !== "idle";
  const [asking, setAsking] = useState<HTMLElement | null>(null);
  const [view, setView] = useState<"rendered" | "source">("rendered");
  const form = useRef<HTMLFormElement>(null);
  return (
    <div className="app-page">
      <PageHead
        crumbs={[{ label: project.name, href: `/p/${project.slug}` }, { label: itemId, href: editor }, { label: "AI draft" }]}
        title={`AI draft from ${draft.client}`}
        lead={
          <>
            Saved <Time at={draft.createdAt} format="exact" />
            {draft.note ? ` · ${draft.note}` : ""}
          </>
        }
        actions={
          <>
            {canEdit ? (
              <Form method="post" ref={form}>
                <Button
                  type="submit"
                  variant="primary"
                  pending={busy}
                  onClick={(event) => {
                    event.preventDefault();
                    setAsking(event.currentTarget);
                  }}
                >
                  Use as my draft
                </Button>
              </Form>
            ) : null}
            <Link to={`${editor}/history?compare=ai&ai=${draft.id}`} className="cap-btn">
              Compare with my draft
            </Link>
            <Link to={editor} className="cap-btn">
              Back to my draft
            </Link>
          </>
        }
      />
      <Banner tone="info">
        Written by an AI session, beside your own draft. It has not changed your draft or the site. Using it replaces your working draft in Carrel with this text, which you then edit
        and save to the site as usual.
      </Banner>
      <FrontmatterFields source={draft.source} readOnly />
      <Panel
        title="The draft"
        src={`${draft.source.trim().split(/\s+/).filter(Boolean).length.toLocaleString()} words`}
        actions={<Segmented legend="View" hideLegend size="sm" value={view} onChange={setView} options={[{ value: "rendered", label: "As it reads" }, { value: "source", label: "Source" }]} />}
      >
        {view === "rendered" ? (
          <div className="app-preview-pane">
            {/* Sandboxed with no permissions, as the editor's preview is: the site's page runs no script. */}
            <iframe title={`This AI draft as the site renders it`} src={`${editor}/ai/${draft.id}/preview`} sandbox="" />
          </div>
        ) : (
          <pre className="app-ai-draft">{draft.source}</pre>
        )}
      </Panel>
      <ConfirmDialog
        open={asking !== null}
        title="Use the AI draft as your draft?"
        lead="Its text replaces your working draft in Carrel, and your current draft is not kept. Nothing is sent to the site: the text waits in the editor until you save it there."
        body={[]}
        action="Replace my draft"
        returnTo={asking}
        perform={async () => {
          // Submitting the form itself does not press the button again, so it does not ask twice.
          form.current?.requestSubmit();
        }}
        onClose={() => setAsking(null)}
      />
    </div>
  );
}

app/routes/legal.tsx.source:
// The Legal tab: a site's privacy and terms pages, and the shared sections they are written from.
// A legal page is an ordinary page on the site, edited in the normal editor; this tab lists them and
// keeps the text every site says alike. Nothing here is a second editor for a page.

import { Form, Link, useNavigation } from "react-router";
import { Alert, Banner } from "capsomer/react/banner";
import { Button } from "capsomer/react/button";
import { Empty } from "capsomer/react/empty";
import { Field } from "capsomer/react/field";
import { Panel } from "capsomer/react/panel";
import { Pill } from "capsomer/react/status";

import { PageHead } from "~/components/page-head";
import { ProjectTabs } from "~/components/project-tabs";

import { readDoc } from "~/lib/content.server";
import { getEnv, getViewer } from "~/lib/context";
import { BANNER_WORD, readFields, splitSource } from "~/lib/frontmatter";
import { LEGAL_TYPES, legalItemId, sectionsUsed, type LegalType } from "~/lib/legal";
import { deleteSection, listSections, saveSection, sectionsCurrent } from "~/lib/legal.server";
import { requireSiteProject } from "~/lib/projects.server";
import { can } from "~/lib/roles";
import { siteEntry, SiteNotConnected } from "~/lib/sites.server";

import type { Route } from "./+types/legal";

export function meta({ loaderData: data }: Route.MetaArgs) {
  return [{ title: data ? `Legal · ${data.project.name} · Carrel` : "Carrel" }];
}

const NAMES: Record<LegalType, string> = { privacy: "Privacy", terms: "Terms" };

export async function loader({ params, context }: Route.LoaderArgs) {
  const env = getEnv(context);
  const project = await requireSiteProject(env.DB, getViewer(context), params.project, "read");
  const sections = await listSections(env.DB);
  let siteError: string | null = null;
  const pages = await Promise.all(
    LEGAL_TYPES.map(async (type) => {
      const id = legalItemId(type);
      try {
        const doc = await readDoc(env, project, id);
        if (!doc) return { type, id, setUp: false as const };
        const fields = readFields(splitSource(doc.source).front);
        return {
          type,
          id,
          setUp: true as const,
          title: doc.title || NAMES[type],
          status: doc.status,
          lastUpdated: fields.last_updated,
          draftBanner: fields.banner === BANNER_WORD,
          version: doc.version,
          shared: sectionsUsed(splitSource(doc.source).body),
          behind: !(await sectionsCurrent(env.DB, doc.source)),
        };
      } catch (error) {
        siteError = error instanceof SiteNotConnected ? error.detail : "The site did not answer.";
        return { type, id, setUp: false as const };
      }
    }),
  );
  return {
    project: { slug: project.slug, name: project.name, site: siteEntry(project.site).name, mentions: can(project.role, "read_mentions") },
    canManage: can(project.role, "manage"),
    siteError,
    pages,
    sections,
  };
}

export async function action({ params, request, context }: Route.ActionArgs) {
  const env = getEnv(context);
  const viewer = getViewer(context);
  const project = await requireSiteProject(env.DB, viewer, params.project, "read");
  const form = await request.formData();
  const intent = String(form.get("intent") ?? "");
  const key = String(form.get("key") ?? "");
  if (intent === "delete-section") {
    await deleteSection(env.DB, project, key);
    return { saved: null, error: null, deleted: key };
  }
  if (intent !== "save-section") throw new Response("Bad request", { status: 400 });
  const result = await saveSection(env.DB, project, viewer, { key, title: String(form.get("title") ?? ""), body: String(form.get("body") ?? "") });
  return result.ok ? { saved: key, error: null, deleted: null } : { saved: null, error: result.message, deleted: null };
}

export default function Legal({ loaderData, actionData }: Route.ComponentProps) {
  const { project, canManage, siteError, pages, sections } = loaderData;
  const navigation = useNavigation();
  const saving = navigation.state !== "idle" ? String(navigation.formData?.get("key") ?? "") : null;

  return (
    <div className="app-page">
      <PageHead title={project.name} lead={`The privacy and terms pages on ${project.site}, and the text every site shares.`} />
      <ProjectTabs slug={project.slug} current="legal" mentions={project.mentions} />

      {siteError ? (
        <Banner tone="warn" title="The site's legal pages could not be read">
          {siteError}
        </Banner>
      ) : null}
      {actionData?.error ? <Alert tone="crit">{actionData.error}</Alert> : null}
      {actionData?.saved ? (
        <Banner tone="ok">
          Saved "{actionData.saved}". A page picks up the new wording when it is next saved to the site, and its date changes when the Owner publishes it.
        </Banner>
      ) : null}
      {actionData?.deleted ? <Banner tone="ok">Removed "{actionData.deleted}". A page that still names it is refused at publish until the marker is removed.</Banner> : null}

      <Panel title="Pages" count={pages.length} src={`${project.site}'s content`} flush>
        <div className="cap-table-wrap" role="region" aria-labelledby="legal-pages-caption" tabIndex={0}>
          <table className="cap-table">
            <caption id="legal-pages-caption" className="cap-sr-only">
              Legal pages on {project.site}
            </caption>
            <thead>
              <tr>
                <th scope="col">Page</th>
                <th scope="col">Status</th>
                <th scope="col">Last updated</th>
                <th scope="col">Shared text</th>
              </tr>
            </thead>
            <tbody>
              {pages.map((page) =>
                page.setUp ? (
                  <tr key={page.id}>
                    <th scope="row">
                      <Link className="cap-table-open" to={`/p/${project.slug}/e/${encodeURIComponent(page.id)}`}>
                        {page.title}
                      </Link>
                      <span className="cap-table-aside">{page.id}</span>
                    </th>
                    <td>
                      {page.status === "published" ? <Pill tone="ok">Published</Pill> : <Pill variant="secondary">Draft</Pill>}
                      {page.draftBanner ? <Pill tone="warn">{BANNER_WORD} banner on</Pill> : null}
                    </td>
                    <td>{page.lastUpdated || "Not set"}</td>
                    <td>
                      {page.shared.length === 0 ? "None" : page.shared.join(", ")}
                      {page.behind ? <Pill tone="warn">Shared text has changed</Pill> : null}
                    </td>
                  </tr>
                ) : (
                  <tr key={page.id}>
                    <th scope="row">{NAMES[page.type]}</th>
                    <td colSpan={3}>Not set up on this site</td>
                  </tr>
                ),
              )}
            </tbody>
          </table>
        </div>
      </Panel>

      <Panel title="Shared sections" count={sections.length} src="Carrel, used by every site">
        <p>
          Write a part once and every site's page can carry it. Put <code>{"{{site_name}}"}</code>, <code>{"{{operator_name}}"}</code>, <code>{"{{contact}}"}</code>,{" "}
          <code>{"{{jurisdiction}}"}</code> or <code>{"{{data_held}}"}</code> in the text and each page fills in its own.
        </p>
        {sections.length === 0 ? (
          <Empty kind="nothing-yet" title="No shared sections yet">
            The parts every site says alike go here.
          </Empty>
        ) : null}
        {sections.map((section) => (
          <Form method="post" key={section.key} className="app-fm" aria-label={`Shared section ${section.key}`}>
            <input type="hidden" name="key" value={section.key} />
            <Field label={`${section.key}: title`}>
              <input className="cap-input" name="title" defaultValue={section.title} readOnly={!canManage} />
            </Field>
            <Field label="Text">
              <textarea className="cap-input" name="body" rows={5} defaultValue={section.body} readOnly={!canManage} />
            </Field>
            {canManage ? (
              <div className="app-actions">
                <Button type="submit" name="intent" value="save-section" pending={saving === section.key}>
                  Save section
                </Button>
                <Button type="submit" name="intent" value="delete-section" variant="danger">
                  Remove
                </Button>
              </div>
            ) : null}
          </Form>
        ))}
        {canManage ? (
          <Form method="post" className="app-fm" aria-label="Add a shared section">
            <Field label="Name" help="Lowercase words joined by hyphens, like cloudflare-hosting.">
              <input className="cap-input" name="key" />
            </Field>
            <Field label="Title">
              <input className="cap-input" name="title" />
            </Field>
            <Field label="Text">
              <textarea className="cap-input" name="body" rows={5} />
            </Field>
            <div className="app-actions">
              <Button type="submit" name="intent" value="save-section" variant="primary">
                Add section
              </Button>
            </div>
          </Form>
        ) : (
          <p>Only the Owner changes shared text.</p>
        )}
      </Panel>
    </div>
  );
}

app/routes/project.tsx.source:
// The one view for a site: every post the site reports, filtered by status and kind, searched with
// FTS5 over title and body. The list is Carrel's index; Refresh asks the site again.

import { ContentStatus } from "@dustinedwards/site-api";
import { useEffect, useRef, useState } from "react";
import { Form, Link, useNavigation, useRevalidator } from "react-router";
import { Alert, Banner } from "capsomer/react/banner";
import { BulkBar } from "capsomer/react/bulk-bar";
import { Button } from "capsomer/react/button";
import { Empty } from "capsomer/react/empty";
import { Field } from "capsomer/react/field";
import { Panel } from "capsomer/react/panel";
import { Select } from "capsomer/react/select";
import { Pill, Status } from "capsomer/react/status";
import { Time } from "capsomer/react/time";

import { PageHead } from "~/components/page-head";
import { ProjectTabs } from "~/components/project-tabs";

import { getEnv, getViewer } from "~/lib/context";
import { contentDeleteOffered } from "~/lib/content.server";
import { kindsIn, refreshIndex, searchItems } from "~/lib/index.server";
import { requireSiteProject } from "~/lib/projects.server";
import { can } from "~/lib/roles";
import { siteConnection, siteEntry } from "~/lib/sites.server";
import { waitingWork, withWaitingWork } from "~/lib/waiting.server";

import type { Route } from "./+types/project";

export function meta({ loaderData: data }: Route.MetaArgs) {
  return [{ title: data ? `${data.project.name} · Carrel` : "Carrel" }];
}

export async function loader({ params, request, context }: Route.LoaderArgs) {
  const env = getEnv(context);
  const project = await requireSiteProject(env.DB, getViewer(context), params.project, "read");
  const url = new URL(request.url);
  const status = ContentStatus.safeParse(url.searchParams.get("status"));
  const filters = {
    q: url.searchParams.get("q")?.trim() || undefined,
    status: status.success ? status.data : undefined,
    kind: url.searchParams.get("kind")?.trim() || undefined,
  };
  const viewer = getViewer(context);
  const [indexed, kinds, waiting] = await Promise.all([
    searchItems(env.DB, project.id, filters),
    kindsIn(env.DB, project.id),
    waitingWork(env.DB, project, viewer),
  ]);
  const items = withWaitingWork(indexed, waiting, filters);
  const connection = siteConnection(env, project.site);
  // Delete is the Owner's, and a site may not offer it. The Owner is told which, and why, beside the actions.
  const canDelete = can(project.role, "delete_content");
  const deleteSupport = canDelete && connection.state === "connected" ? await contentDeleteOffered(env, project) : null;
  return {
    canDelete,
    deleteOffered: deleteSupport?.offered === true,
    deleteReason: deleteSupport && !deleteSupport.offered ? deleteSupport.reason : null,
    project: { slug: project.slug, name: project.name, site: siteEntry(project.site).name, mentions: can(project.role, "read_mentions") },
    canEdit: can(project.role, "edit"),
    connected: connection.state === "connected",
    connectionDetail: connection.state === "connected" ? null : connection.detail,
    filters,
    kinds,
    items,
  };
}

export async function action({ params, request, context }: Route.ActionArgs) {
  const env = getEnv(context);
  const project = await requireSiteProject(env.DB, getViewer(context), params.project, "read");
  const form = await request.formData();
  if (form.get("intent") !== "refresh") throw new Response("Bad request", { status: 400 });
  try {
    const result = await refreshIndex(env, { id: project.id, site: project.site });
    return { refreshed: result, error: null };
  } catch (error) {
    return { refreshed: null, error: error instanceof Error ? error.message : String(error) };
  }
}

function when(iso: string | null): string {
  if (!iso) return "";
  const date = new Date(iso);
  return Number.isNaN(date.getTime()) ? iso : date.toISOString().slice(0, 10);
}

type BulkOutcome = { id: string; title: string; ok: boolean; message: string; copyId?: string };
type BulkOp = "tag-add" | "tag-remove" | "duplicate" | "delete";

const DONE = "Done. The result for each post is listed below the table.";

export default function Project({ loaderData, actionData }: Route.ComponentProps) {
  const { project, canEdit, canDelete, deleteOffered, deleteReason, connected, connectionDetail, filters, kinds, items } = loaderData;
  const navigation = useNavigation();
  const revalidator = useRevalidator();
  // The selection is by post id; a post no longer listed (a filter, a delete) drops out of it.
  const [selected, setSelected] = useState<string[]>([]);
  const [tag, setTag] = useState("");
  const [result, setResult] = useState<{ what: string; outcomes: BulkOutcome[] } | null>(null);
  const resultRef = useRef<HTMLElement>(null);
  // Only a post the site holds can be acted on; one that exists only in Carrel (an AI draft for a new post) cannot.
  const selectable = items.filter((i) => !i.isNew);
  const chosen = selectable.filter((i) => selected.includes(i.itemId));
  useEffect(() => {
    if (!result) return;
    const el = resultRef.current;
    if (el) {
      el.tabIndex = -1;
      el.focus();
    }
  }, [result]);

  const run = (op: BulkOp, what: string) => async (picked: readonly { id: string; label: string }[]) => {
    if ((op === "tag-add" || op === "tag-remove") && tag.trim() === "") throw new Error("Type a tag first.");
    const form = new FormData();
    form.set("op", op);
    if (op === "tag-add" || op === "tag-remove") form.set("tag", tag);
    for (const p of picked) form.append("id", p.id);
    const response = await fetch(`/p/${encodeURIComponent(project.slug)}/bulk`, { method: "POST", body: form, headers: { accept: "application/json" } });
    const body = (await response.json().catch(() => null)) as { results?: BulkOutcome[]; error?: string } | null;
    if (!response.ok || !body?.results) throw new Error(body?.error ?? `The server answered ${response.status}.`);
    setResult({ what, outcomes: body.results });
    void revalidator.revalidate();
  };
  const refreshing = navigation.state !== "idle" && navigation.formData?.get("intent") === "refresh";
  const filtered = Boolean(filters.q || filters.status || filters.kind);

  return (
    <div className="app-page">
      <PageHead
        title={project.name}
        lead={`Everything on ${project.site}, from Carrel's index of the site.`}
        actions={
          <>
            {connected ? (
              <Form method="post">
                <Button type="submit" name="intent" value="refresh" pending={refreshing}>
                  {refreshing ? "Refreshing" : "Refresh from the site"}
                </Button>
              </Form>
            ) : null}
            {canEdit && connected ? (
              <Link to="new" className="cap-btn" data-variant="primary">
                New post
              </Link>
            ) : null}
          </>
        }
      />

      <ProjectTabs slug={project.slug} current="posts" mentions={project.mentions} />

      {!connected ? (
        <Banner tone="warn" title="This site is not connected yet">
          {connectionDetail} Posts appear here once the site's key is set.
        </Banner>
      ) : null}

      {actionData?.error ? (
        <Alert tone="crit">The site could not be read: {actionData.error}</Alert>
      ) : actionData?.refreshed ? (
        <Banner tone="ok">
          {actionData.refreshed.listed} posts listed, {actionData.refreshed.fetched} read in full
          {actionData.refreshed.pending > 0 ? `, ${actionData.refreshed.pending} more on the next refresh` : ""}.
        </Banner>
      ) : null}

      {result ? (
        <Panel
          title="Result"
          id="bulk-result"
          ref={resultRef}
          src={`${result.what}: ${result.outcomes.filter((o) => o.ok).length} of ${result.outcomes.length} done`}
          actions={
            <Button size="sm" onClick={() => setResult(null)}>
              Clear this result
            </Button>
          }
        >
          <ul className="app-flags" aria-label="Result for each post">
            {result.outcomes.map((o) => (
              <li key={o.id}>
                {o.ok ? <Status tone="ok">Done</Status> : <Status tone="crit">Left as it was</Status>}
                <span>
                  <strong>{o.title}</strong> <span className="cap-mono cap-muted">{o.id}</span>
                  <br />
                  {o.message}
                  {o.copyId ? (
                    <>
                      {" "}
                      <Link to={`e/${encodeURIComponent(o.copyId)}`}>Open the copy</Link>
                    </>
                  ) : null}
                </span>
              </li>
            ))}
          </ul>
        </Panel>
      ) : null}

      <Panel title="Posts" count={items.length} src={`Carrel's index of ${project.site}`} flush>
        <div className="cap-panel-pad">
          <Form method="get" className="app-filters" role="search" aria-label="Filter posts">
            <Field label="Search">
              <input className="cap-input" type="search" name="q" defaultValue={filters.q ?? ""} placeholder="Words in the title or text" />
            </Field>
            <Field label="Status">
              <Select
                name="status"
                defaultValue={filters.status ?? ""}
                options={[
                  { value: "", label: "Any" },
                  { value: "draft", label: "Draft" },
                  { value: "scheduled", label: "Scheduled" },
                  { value: "published", label: "Published" },
                ]}
              />
            </Field>
            {kinds.length > 1 ? (
              <Field label="Kind">
                <Select name="kind" defaultValue={filters.kind ?? ""} options={[{ value: "", label: "Any" }, ...kinds.map((k) => ({ value: k, label: k }))]} />
              </Field>
            ) : null}
            <div className="app-actions">
              <Button type="submit" variant="primary">
                Filter
              </Button>
              {filtered ? (
                <Link to="." className="cap-btn">
                  Clear
                </Link>
              ) : null}
            </div>
          </Form>
        </div>

        {items.length === 0 ? (
          <Empty kind={filtered ? "no-match" : "nothing-yet"} flush title={filtered ? "No posts match" : "No posts in the index yet"} action={filtered ? <Link to="." className="cap-btn">Clear the filter</Link> : undefined}>
            {filtered ? "Nothing on this site fits the search and filters above." : "Refresh from the site to read what it has."}
          </Empty>
        ) : (
          <div className="cap-table-wrap" role="region" aria-labelledby="posts-caption" tabIndex={0}>
            <table className="cap-table">
              <caption id="posts-caption" className="cap-sr-only">
                Posts on {project.site}
              </caption>
              <thead>
                <tr>
                  {canEdit ? (
                    <th scope="col">
                      <span className="cap-sr-only">Select</span>
                    </th>
                  ) : null}
                  <th scope="col">Title</th>
                  {kinds.length > 1 ? <th scope="col">Kind</th> : null}
                  <th scope="col">Status</th>
                  <th scope="col">Updated</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.itemId} data-state={selected.includes(item.itemId) ? "selected" : undefined}>
                    {canEdit ? (
                      <td>
                        <label className="cap-check">
                          <input
                            type="checkbox"
                            checked={selected.includes(item.itemId)}
                            disabled={item.isNew}
                            onChange={(event) => setSelected((now) => (event.target.checked ? [...now, item.itemId] : now.filter((id) => id !== item.itemId)))}
                          />
                          <span className="cap-sr-only">
                            Select {item.title || item.itemId}
                            {item.isNew ? " (only in Carrel, so it cannot be acted on in bulk)" : ""}
                          </span>
                        </label>
                      </td>
                    ) : null}
                    <th scope="row">
                      <Link className="cap-table-open" to={`e/${encodeURIComponent(item.itemId)}`}>
                        {item.title || item.itemId}
                      </Link>
                      <span className="cap-table-aside">{item.path ?? item.itemId}</span>
                    </th>
                    {kinds.length > 1 ? <td>{item.kind}</td> : null}
                    <td>
                      {item.status === "published" ? (
                        <Pill tone="ok">Published</Pill>
                      ) : item.status === "scheduled" ? (
                        <Pill tone="info">Scheduled{item.publishAt ? ` ${when(item.publishAt)}` : ""}</Pill>
                      ) : (
                        <Pill variant="secondary">{item.isNew ? "New draft" : "Draft"}</Pill>
                      )}
                      {item.aiDrafts > 0 ? (
                        <Pill tone="info">
                          {item.aiDrafts === 1 ? "1 AI draft waiting" : `${item.aiDrafts} AI drafts waiting`}
                        </Pill>
                      ) : null}
                    </td>
                    <td>{item.updatedAt ? <Time at={item.updatedAt} /> : null}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Panel>

      {canEdit ? (
        <BulkBar
          items={chosen.map((i) => ({ id: i.itemId, label: `${i.title || i.itemId} (${i.itemId})` }))}
          total={selectable.length}
          onSelectAll={() => setSelected(selectable.map((i) => i.itemId))}
          onClear={() => setSelected([])}
          actions={[
            { id: "tag-add", label: "Add tag", said: DONE, run: run("tag-add", "Add tag") },
            { id: "tag-remove", label: "Remove tag", said: DONE, run: run("tag-remove", "Remove tag") },
            { id: "duplicate", label: "Duplicate", said: DONE, run: run("duplicate", "Duplicate") },
            ...(canDelete && deleteOffered
              ? [
                  {
                    id: "delete",
                    label: "Delete",
                    destructive: true,
                    confirmTitle: "Delete {n} post{s} from the site?",
                    confirmLead: `Each post below is removed from ${project.site}. Carrel cannot bring one back; the site's own history may still hold its text. Your working drafts of them stay in Carrel.`,
                    confirmAction: "Delete {n} post{s}",
                    said: DONE,
                    run: run("delete", "Delete"),
                  },
                ]
              : []),
          ]}
        >
          <span className="cap-bulk-field">
            <label htmlFor="bulk-tag">Tag</label>
            <input className="cap-input" id="bulk-tag" value={tag} onChange={(event) => setTag(event.target.value)} autoComplete="off" />
          </span>
          {canDelete && deleteReason ? <span className="cap-bulk-detail">Delete is not offered: {deleteReason}</span> : null}
        </BulkBar>
      ) : null}
    </div>
  );
}

test/kinds.test.ts.source:
// Every kind the site reports, end to end through the routes: a non-post kind lists under its own
// kind and filter, opens, saves, previews, publishes and shows its revisions exactly as a post does,
// and a data kind the site will not write stays out of the lists and, if reached, shows the site's
// own refusal. Carrel has no per-kind code; the kinds and paths come from the site.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { refreshIndex } from "~/lib/index.server";
import { action as editorAction, loader as editorLoader } from "~/routes/editor";
import { loader as historyLoader } from "~/routes/history";
import { loader as previewLoader } from "~/routes/preview";
import { loader as projectLoader } from "~/routes/project";

import { addPerson, addProject, resetDb } from "./env";
import { connectedEnv, fakeSite, kindedAdapter, viewerFor } from "./site";

const SLUG = "de-info";
const OWNER = "owner@test.invalid";
let projectId = 0;

beforeEach(async () => {
  await resetDb();
  await addPerson(OWNER, { owner: true });
  projectId = await addProject(SLUG, "dustinedwards");
});

async function contextFor(env: Env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(OWNER));
  context.set(nonceContext, "test-nonce");
  return context;
}

async function settled<T>(run: () => Promise<T>): Promise<T | Response> {
  try {
    return await run();
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function seeded() {
  const site = fakeSite(kindedAdapter());
  vi.stubGlobal("fetch", site.fetch);
  const env = connectedEnv();
  const put = async (id: string, source: string, publish: boolean) => {
    const saved = await site.adapter.content.saveDraft(id, { source, expectedVersion: null, changeId: `seed-${id}` });
    if (publish) await site.adapter.content.publish(id, { expectedVersion: saved.version, changeId: `seed-pub-${id}` });
  };
  await put("a-post", "---\ntitle: A post\n---\nWords.\n", true);
  await put("draft-post", "---\ntitle: A draft post\n---\nNot yet.\n", false);
  await put("phage.acorn15", "---\ntitle: Acorn15\nhost: Gordonia\n---\nA cluster DJ phage.\n", true);
  await put("roster.2017", "---\ntitle: 2017 cohort\nyear: 2017\n---\n", true);
  await put("procedure.coi-primers", "---\ntitle: COI primers\n---\nThe PCR protocol.\n", true);
  await refreshIndex(env, { id: projectId, site: "dustinedwards" });
  return { site, env };
}

const form = (fields: Record<string, string>) => {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  return body;
};

describe("every kind the site reports", () => {
  it("lists each writing kind under its own kind, and the kind filter narrows to it", async () => {
    const { env } = await seeded();
    const context = await contextFor(env);
    const all = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(all.kinds).toEqual(["phage", "post", "procedure", "roster"]);
    const byId = Object.fromEntries(all.items.map((i) => [i.itemId, i]));
    expect(byId["phage.acorn15"]).toMatchObject({ kind: "phage", path: "/research/phages#acorn15", status: "published" });
    expect(byId["roster.2017"]).toMatchObject({ kind: "roster", path: "/teaching/phage-discovery#year-2017" });
    expect(byId["procedure.coi-primers"]).toMatchObject({ kind: "procedure", path: "/research/protocols/coi-primers" });
    expect(byId["draft-post"]).toMatchObject({ kind: "post", status: "draft", path: null });

    const phages = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}?kind=phage`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(phages.items.map((i) => i.itemId)).toEqual(["phage.acorn15"]);
  });

  it("opens, saves, previews, publishes and shows the history of a non-post kind", async () => {
    const { env, site } = await seeded();
    const id = "phage.acorn15";
    const params = { project: SLUG, item: id };
    const url = `https://carrel.test/p/${SLUG}/e/${id}`;

    const opened = (await editorLoader({ request: new Request(url), params, context: await contextFor(env) } as never)) as Awaited<ReturnType<typeof editorLoader>>;
    expect(opened.title).toBe("Acorn15");
    expect(opened.path).toBe("/research/phages#acorn15");
    // Links written in the editor go to each item's own address on the site, a draft post to where the site's posts live.
    expect(opened.linkTargets.map((t) => t.href).sort()).toEqual([
      "/research/protocols/coi-primers",
      "/teaching/phage-discovery#year-2017",
      "/writing/a-post",
      "/writing/draft-post",
    ]);

    const source = "---\ntitle: Acorn15\nhost: Gordonia terrae\n---\nA cluster DJ phage, found in 2015.\n";
    const saved = await editorAction({ request: new Request(url, { method: "POST", body: form({ intent: "save", source, expectedVersion: opened.version! }) }), params, context: await contextFor(env) } as never);
    expect(saved).toMatchObject({ intent: "write", outcome: { ok: true, action: "save", status: "published" } });
    const version = (saved as { outcome: { version: string } }).outcome.version;

    const previewed = (await settled(async () => previewLoader({ request: new Request(`${url}/preview`), params, context: await contextFor(env) } as never))) as Response;
    expect(previewed.status).toBe(200);
    expect(await previewed.text()).toContain("found in 2015");

    const published = await editorAction({ request: new Request(url, { method: "POST", body: form({ intent: "publish", source, expectedVersion: version }) }), params, context: await contextFor(env) } as never);
    expect(published).toMatchObject({ intent: "write", outcome: { ok: true, action: "publish", status: "published" } });
    expect((await site.adapter.content.get(id))?.source).toContain("found in 2015");

    const history = (await historyLoader({ request: new Request(`${url}/history`), params, context: await contextFor(env) } as never)) as { revisions: unknown[] | null };
    expect(history.revisions?.length).toBe(4);
  });

  it("keeps a data kind out of the lists, and shows the site's own refusal if one is written", async () => {
    const { env, site } = await seeded();
    // The site's import puts registry rows in place directly; Carrel never wrote them.
    await env.DB.prepare("INSERT INTO site_items (project_id, item_id, kind, title, status, synced_at) VALUES (?, 'equipment.heat-block', 'equipment', 'Heat block', 'published', '2026-10-10T00:00:00Z')").bind(projectId).run();
    const context = await contextFor(env);
    const listed = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(listed.kinds).not.toContain("equipment");
    expect(listed.items.map((i) => i.itemId)).not.toContain("equipment.heat-block");

    const params = { project: SLUG, item: "equipment.heat-block" };
    const written = await editorAction({
      request: new Request(`https://carrel.test/p/${SLUG}/e/equipment.heat-block`, { method: "POST", body: form({ intent: "save", source: "---\nname: Heat block\n---\n", expectedVersion: "" }) }),
      params,
      context: await contextFor(env),
    } as never);
    expect(written).toMatchObject({ intent: "write", outcome: { ok: false, reason: "refused", message: "The site's equipment entries are edited in the site's repository, not through Carrel." } });
    expect(await site.adapter.content.get("equipment.heat-block")).toBeNull();
  });
});

test/routes.test.ts.source:
// The editor's routes, driven through their loaders and actions with a real request context: the
// preview is private to each person and sandboxed, and a first publish asks before it acts.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { autosave } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { action as editorAction } from "~/routes/editor";
import { loader as previewLoader } from "~/routes/preview";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
});

async function contextFor(email: string, env: Env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "test-nonce");
  return context;
}

async function preview(email: string, env: Env) {
  const context = await contextFor(email, env);
  const request = new Request(`https://carrel.test/p/${SLUG}/e/post-one/preview`);
  try {
    return (await previewLoader({ request, params: { project: SLUG, item: "post-one" }, context } as never)) as Response;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function post(email: string, env: Env, fields: Record<string, string>) {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  const request = new Request(`https://carrel.test/p/${SLUG}/e/post-one`, { method: "POST", body });
  return editorAction({ request, params: { project: SLUG, item: "post-one" }, context: await contextFor(email, env) } as never);
}

async function seedPost(site: ReturnType<typeof fakeSite>) {
  const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Site copy\n---\nOn the site.\n", expectedVersion: null, changeId: "seed" });
  return saved.version;
}

describe("the preview", () => {
  it("renders the viewer's own draft through the site, sandboxed and frameable by Carrel only", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(env.DB, owner, SLUG, "read");
    await autosave(env.DB, project, owner, "post-one", { source: "---\ntitle: Owner draft\n---\nNot on the site.\n", baseVersion: version });

    const response = await preview("owner@test.invalid", env);
    expect(response.status).toBe(200);
    expect(response.headers.get("Content-Security-Policy")).toMatch(/^sandbox; default-src 'none'/);
    expect(response.headers.get("X-Frame-Options")).toBe("SAMEORIGIN");
    const html = await response.text();
    expect(html).toContain("Owner draft");
    expect(html).toContain('<base href="https://site.test/">');
  });

  it("PLANT: never shows one person's working draft to another", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);
    const editor = await viewerFor("editor@test.invalid");
    const project = await requireSiteProject(env.DB, editor, SLUG, "edit");
    await autosave(env.DB, project, editor, "post-one", { source: "---\ntitle: Editor secret\n---\nx\n", baseVersion: version });

    const html = await (await preview("reader@test.invalid", env)).text();
    expect(html).toContain("Site copy");
    expect(html).not.toContain("Editor secret");
  });

  it("PLANT: refuses a non-member with the same 404 as a missing project", async () => {
    vi.stubGlobal("fetch", fakeSite().fetch);
    expect((await preview("stranger@test.invalid", connectedEnv())).status).toBe(404);
  });

  it("explains a site that is not connected inside the frame instead of failing", async () => {
    const response = await preview("owner@test.invalid", testEnv);
    expect(response.status).toBe(200);
    expect(await response.text()).toContain("not connected");
  });
});

describe("publishing from the editor", () => {
  it("asks before a first publish, and publishes on the explicit second ask", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);

    const ask = await post("owner@test.invalid", env, { intent: "publish", expectedVersion: version, source: "---\ntitle: Site copy\n---\nOn the site.\n" });
    expect(ask).toEqual({ intent: "publish", needsConfirm: true });
    expect(site.adapter.store.get("post-one")!.doc.status).toBe("draft");

    const done = await post("owner@test.invalid", env, {
      intent: "publish",
      confirm: "first-publish",
      expectedVersion: version,
      source: "---\ntitle: Site copy\n---\nOn the site.\n",
    });
    expect(done).toMatchObject({ intent: "write", outcome: { ok: true, status: "published" } });
  });

  it("PLANT: refuses an Editor's publish from the editor, confirmed or not", async () => {
    const site = fakeSite();
    vi.stubGlobal("fetch", site.fetch);
    const env = connectedEnv();
    const version = await seedPost(site);
    await expect(
      post("editor@test.invalid", env, { intent: "publish", confirm: "first-publish", expectedVersion: version, source: "x" }),
    ).rejects.toSatisfy((thrown: unknown) => thrown instanceof Response && thrown.status === 403);
    expect(site.adapter.store.get("post-one")!.doc.status).toBe("draft");
  });
});

test/waiting.test.ts.source:
// Work waiting on a person that the site does not know yet: an AI draft for a new slug is listed in
// the project's Posts, opens in the editor and previews as the AI draft; an indexed post carries a
// count of AI drafts waiting. All of it private to the person the drafts belong to.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { autosave } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { refreshIndex } from "~/lib/index.server";
import { requireSiteProject } from "~/lib/projects.server";
import { titleOf } from "~/lib/waiting.server";
import { loader as editorLoader } from "~/routes/editor";
import { loader as previewLoader } from "~/routes/preview";
import { loader as projectLoader } from "~/routes/project";

import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;
let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function aiDraft(email: string, item: string, source: string) {
  const viewer = await viewerFor(email);
  const project = await requireSiteProject(env.DB, viewer, SLUG, "edit");
  await saveAiDraft(env, project, { viewer, client: "Claude" }, item, { source });
}

async function list(email: string, query = "") {
  const request = new Request(`https://carrel.test/p/${SLUG}${query}`);
  return (await projectLoader({ request, params: { project: SLUG }, context: await context(email) } as never)).items;
}

const NEW_POST = "---\ntitle: A desk apart\n---\nWords for a new post.\n";

describe("the project's Posts list", () => {
  it("lists an AI draft for a post the site does not have, and its editor opens", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    const items = await list("owner@test.invalid");
    expect(items).toHaveLength(1);
    expect(items[0]).toMatchObject({ itemId: "a-desk-apart", title: "A desk apart", status: "draft", isNew: true, aiDrafts: 1 });

    const page = await editorLoader({ params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never);
    expect(page.source).toBe("");
    expect(page.aiDrafts).toHaveLength(1);
  });

  it("includes it under the Draft filter and the search, and leaves it out of Published and a kind", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    expect(await list("owner@test.invalid", "?status=draft")).toHaveLength(1);
    expect(await list("owner@test.invalid", "?q=desk")).toHaveLength(1);
    expect(await list("owner@test.invalid", "?q=elephant")).toHaveLength(0);
    expect(await list("owner@test.invalid", "?status=published")).toHaveLength(0);
    expect(await list("owner@test.invalid", "?kind=post")).toHaveLength(0);
  });

  it("lists a draft of the person's own for a new post too", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(env.DB, owner, SLUG, "edit");
    await autosave(env.DB, project, owner, "mine", { source: "---\ntitle: Mine\n---\nx\n", baseVersion: null });
    const items = await list("owner@test.invalid");
    expect(items[0]).toMatchObject({ itemId: "mine", title: "Mine", isNew: true, ownDraft: true, aiDrafts: 0 });
  });

  it("marks an indexed post that has AI drafts waiting, with the count", async () => {
    const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nOn the site.\n", expectedVersion: null, changeId: "s" });
    expect(saved.version).toBeTruthy();
    await refreshIndex(env, { id: projectId, site: "dustinedwards" });
    await aiDraft("owner@test.invalid", "post-one", "A better take.");
    await aiDraft("owner@test.invalid", "post-one", "Another take.");
    const items = await list("owner@test.invalid");
    expect(items).toHaveLength(1);
    expect(items[0]).toMatchObject({ itemId: "post-one", isNew: false, aiDrafts: 2 });
  });

  it("PLANT: shows nobody else's AI drafts, and the editor of one still answers 404", async () => {
    await aiDraft("editor@test.invalid", "a-desk-apart", NEW_POST);
    expect(await list("owner@test.invalid")).toHaveLength(0);
    await expect(editorLoader({ params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never)).rejects.toMatchObject({ status: 404 });
  });
});

describe("the preview of an AI-draft-only post", () => {
  it("renders the AI draft through the site, labelled as an AI draft", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    const request = new Request(`https://carrel.test/p/${SLUG}/e/a-desk-apart/preview`);
    const response = (await previewLoader({ request, params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never)) as Response;
    const html = await response.text();
    expect(html).toContain("A desk apart");
    expect(html).toContain("AI draft from Claude. It is not your draft and it is not on the site.");
  });

  it("still says there is nothing to preview when there is no AI draft either", async () => {
    const request = new Request(`https://carrel.test/p/${SLUG}/e/none/preview`);
    const response = (await previewLoader({ request, params: { project: SLUG, item: "none" }, context: await context("owner@test.invalid") } as never)) as Response;
    expect(await response.text()).toContain("There is nothing to preview yet.");
  });
});

describe("titleOf", () => {
  it("reads a plain or quoted frontmatter title, and nothing when there is none", () => {
    expect(titleOf("---\ntitle: Plain\n---\nx")).toBe("Plain");
    expect(titleOf('---\ntitle: "Quoted: yes"\n---\nx')).toBe("Quoted: yes");
    expect(titleOf("No frontmatter\ntitle: nope")).toBe("");
  });
});

test/social.test.ts.source:
// The social queue (design decision 5) against fake Bluesky, X and routine endpoints. Planted: a reply
// attempt refused; a post failing the lint held; the template used only after the routine fails; the
// health email when a template post goes out. Nothing here reaches a real platform.

import { beforeEach, describe, expect, it } from "vitest";

import { writeToSite } from "~/lib/content.server";
import { runHealth } from "~/lib/health.server";
import { requireSiteProject } from "~/lib/projects.server";
import { lintPost } from "~/lib/social/lint";
import { assertOriginalPost, clearBlueskySessions, oauthSignature, percentEncode, SocialRefused } from "~/lib/social/platforms.server";
import {
  BATCH_DELAY_MS,
